#!/usr/bin/env node
/**
 * Generate demo/config.js from FLAGSMITH_ENVIRONMENT_KEY in .env.
 * The generated file is git-ignored; the key never enters the repo.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const env = {};
try {
  for (const line of readFileSync(join(root, ".env"), "utf-8").split("\n")) {
    const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/);
    if (m) env[m[1]] = m[2].trim();
  }
} catch {
  console.error("No .env found. Copy .env.example to .env and set FLAGSMITH_ENVIRONMENT_KEY.");
  process.exit(1);
}
const key = env.FLAGSMITH_ENVIRONMENT_KEY;
if (!key) {
  console.error("FLAGSMITH_ENVIRONMENT_KEY is empty in .env.");
  process.exit(1);
}
writeFileSync(
  join(root, "demo", "config.js"),
  `// Generated by \`npm run demo:config\` from .env — git-ignored, do not commit.\nwindow.FLOWBOARD_CONFIG = { environmentID: ${JSON.stringify(key)} };\n`,
);
console.log("demo/config.js written (environment key set, git-ignored).");
